function SideTables({p,id}:{p:Product;id:string}){const wood=useCanvasTexture('wood'),stone=useCanvasTexture('stone');return <Selectable category="sideTables" itemId={id}><group>{[-3.35,3.35].map(x=><group key={x}>{p.tier==='premium'?<><mesh position={[x,.75,-4.25]}><cylinderGeometry args={[.82,.75,1.5,28]}/><meshStandardMaterial map={wood} color="#8e6548" roughness={.8}/></mesh>{Array.from({length:12},(_,i)=><mesh key={i} position={[x+Math.sin(i/12*Math.PI*2)*.79,.75,-4.25+Math.cos(i/12*Math.PI*2)*.79]}><boxGeometry args={[.025,1.25,.025]}/><meshStandardMaterial color="#5d3e2d"/></mesh>)}</>:p.tier==='mid'?<group><mesh position={[x,.42,-4.25]}><cylinderGeometry args={[.52,.68,.82,24]}/><meshStandardMaterial map={stone} color="#cbbda8" roughness={.9}/></mesh><mesh position={[x,1,-4.25]}><cylinderGeometry args={[.82,.82,.25,24]}/><meshStandardMaterial map={stone} color="#d6c8b4"/></mesh></group>:<group><mesh position={[x,1,-4.25]}><boxGeometry args={[1.35,.12,1.35]}/><meshStandardMaterial color="#f2f2ee"/></mesh>{[-.5,.5].flatMap(dx=>[-.5,.5].map(dz=><mesh key={`${dx}${dz}`} position={[x+dx,.48,-4.25+dz]}><boxGeometry args={[.06,.95,.06]}/><meshStandardMaterial color="#d8dad7"/></mesh>))}</group>}</group>)}</group></Selectable>}
